4	/** A job may be attempted at most this many times in total. */
5	export const MAX_ATTEMPTS = 3;
6	
7	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
8	
9	/** The public job shape returned by every endpoint that returns a job. */
10	export interface Job {
11	  id: string;
12	  status: JobStatus;
13	  input: string;
14	  steps: number;
15	  failAttempts: number;
16	  attempts: number;
17	  progress: { completed: number; total: number };
18	  result: { output: string } | null;
19	  error: string | null;
20	  createdAt: string;
21	  updatedAt: string;
22	}
23	
24	/** A row of the `jobs` table. */
25	export interface JobRow {
26	  seq: number;
27	  id: string;
28	  status: JobStatus;
29	  input: string;
30	  steps: number;
31	  fail_attempts: number;
32	  attempts: number;
33	  completed: number;
34	  result_output: string | null;
35	  error: string | null;
36	  idempotency_key: string | null;
37	  next_run_at: number;
38	  created_at: string;
39	  updated_at: string;
40	}
41	
42	export const JOB_COLUMNS =
43	  'seq, id, status, input, steps, fail_attempts, attempts, completed, result_output, error, idempotency_key, next_run_at, created_at, updated_at';
44	
45	export const iso = (ms: number): string => new Date(ms).toISOString();
46	
47	export function toJob(row: JobRow): Job {
48	  return {
49	    id: row.id,
50	    status: row.status,
51	    input: row.input,
52	    steps: row.steps,
53	    failAttempts: row.fail_attempts,
54	    attempts: row.attempts,
55	    progress: { completed: row.completed, total: row.steps },
56	    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
57	    error: row.status === 'failed' ? (row.error ?? '') : null,
58	    createdAt: row.created_at,
59	    updatedAt: row.updated_at,
60	  };
61	}
62	
63	export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
64	  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as unknown as JobRow | undefined;
65	}
66	
67	export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
68	  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key) as unknown as JobRow | undefined;
69	}
70	
71	/** All jobs, newest first. */
72	export function listJobRows(db: DatabaseSync): JobRow[] {
73	  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
74	}
75	
