import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** A job may be attempted at most this many times in total. */
export const MAX_ATTEMPTS = 3;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

export const JOB_COLUMNS =
  'seq, id, status, input, steps, fail_attempts, attempts, completed, result_output, error, idempotency_key, next_run_at, created_at, updated_at';

export const iso = (ms: number): string => new Date(ms).toISOString();

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? '') : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as unknown as JobRow | undefined;
}

export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first. */
export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
}

export function insertJob(db: DatabaseSync, job: NewJob, nowMs: number): JobRow {
  const id = randomUUID();
  const now = iso(nowMs);
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now, now);
  return getJobRow(db, id)!;
}

