export interface FieldError {
  field: string;
  message: string;
}

export type Parsed<T> = { ok: true; value: T } | { ok: false; fields: FieldError[] };

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function checkInteger(name: string, value: unknown, min: number, max: number, fields: FieldError[]): number {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return min;
  }
  if (value < min || value > max) fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  return value;
}

/** Validates a POST /api/jobs body. Defaults are applied to optional fields. */
export function parseSubmission(contentType: string | undefined, text: string): Parsed<Submission> {
  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    return { ok: false, fields: [{ field: 'body', message: 'Content-Type must be application/json' }] };
  }
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'body is not valid JSON' }] };
  }
  if (!isPlainObject(body)) return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };

  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const rawInput = body.input;
  if (rawInput === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (rawInput.trim().length === 0) {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = rawInput;
  }

  const steps = body.steps === undefined ? 5 : checkInteger('steps', body.steps, 1, 20, fields);
  const failAttempts = body.failAttempts === undefined ? 0 : checkInteger('failAttempts', body.failAttempts, 0, 5, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

/** Validates the optional Idempotency-Key header. Returns null when it is absent. */
export function parseIdempotencyKey(header: string | undefined): Parsed<string | null> {
  if (header === undefined) return { ok: true, value: null };
  if (!IDEMPOTENCY_KEY_RE.test(header)) {
    return { ok: false, fields: [{ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' }] };
  }
  return { ok: true, value: header };
}

